def ask_data(question: str) -> list:
    prompt = f"Schema:\n{SCHEMA}\nWrite one SQLite query answering: {question}\nReturn only SQL."
    sql = llm.complete(prompt).strip()
    if not sql.lower().startswith("select") or ";" in sql.rstrip(";"):
        raise ValueError("only single SELECT statements are allowed")
    with readonly_db.connect() as conn:  # separate read-only role
        return conn.execute(sql).fetchmany(1000)

